using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class AccountRepository(NamaaDbContext db):IAccountRepository{public Task<bool>ExistsByAccountCodeAsync(string value,CancellationToken cancellationToken=default)=>db.Accounts.AsNoTracking().AnyAsync(e=>e.AccountCode==value,cancellationToken);public Task<Account?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.Accounts.AsNoTracking().SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public Task<Account?>FindForUpdateAsync(long id,CancellationToken cancellationToken=default)=>db.Accounts.SingleOrDefaultAsync(e=>e.Id==id,cancellationToken);public async Task<IReadOnlyList<Account>>GetAllAsync(CancellationToken cancellationToken=default)=>await db.Accounts.AsNoTracking().OrderBy(e=>e.Id).ToListAsync(cancellationToken);public async Task AddAsync(Account entity,CancellationToken cancellationToken=default)=>await db.Accounts.AddAsync(entity,cancellationToken);}
